import{_ as o,C as a,c as s,o as d,aj as l,j as t,G as n,a as h,w as c}from"./chunks/framework.Bfdr4H5E.js";const T=JSON.parse('{"title":"Chart Timeframes","description":"","frontmatter":{"outline":"deep","prev":{"text":"Anatomy of a Candlestick","link":"/trading-with-pav/anatomy-of-a-candlestick"},"next":{"text":"Charting Platform","link":"/trading-with-pav/charting-platform.md"}},"headers":[],"relativePath":"trading-with-pav/chart-timeframes.md","filePath":"trading-with-pav/chart-timeframes.md"}'),m={name:"trading-with-pav/chart-timeframes.md"};function y(u,e,g,p,f,x){const i=a("GraphComment"),r=a("ClientOnly");return d(),s("div",null,[e[0]||(e[0]=l('<h1 id="chart-timeframes" tabindex="-1">Chart Timeframes <a class="header-anchor" href="#chart-timeframes" aria-label="Permalink to &quot;Chart Timeframes&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Content</p><nav class="table-of-contents"><ul><li><a href="#a-note-on-time-frames">A note on time frames</a></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="a-note-on-time-frames" tabindex="-1">A note on time frames <a class="header-anchor" href="#a-note-on-time-frames" aria-label="Permalink to &quot;A note on time frames&quot;">​</a></h2><p>A time frame is defined as the time duration during which one chooses to study a particular chart. Some of the popular time frames that technical analysts use are:</p><ul><li>Monthly Charts</li><li>Weekly charts</li><li>Daily or End of day charts</li><li>Intraday charts – 30 Mins, 15 mins and 5 minutes</li></ul><p>One can customize the time frame as per their requirement. For example, a high-frequency trader may want to use a 1-minute chart instead of any other time frame.</p><p>Here is a quick note on different types of time frames.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Time Frame</th><th style="text-align:center;">Open</th><th style="text-align:center;">High</th><th style="text-align:center;">Low</th><th style="text-align:center;">Close</th><th style="text-align:center;">No of Candles</th></tr></thead><tbody><tr><td style="text-align:center;">Monthly</td><td style="text-align:center;">The opening price on the first day of the month</td><td style="text-align:center;">The highest price at which the stock traded during the entire month</td><td style="text-align:center;">The lowest price at which the stock traded during the entire month</td><td style="text-align:center;">The closing price on the last day of the month</td><td style="text-align:center;">12 candles for the entire year</td></tr><tr><td style="text-align:center;">Weekly</td><td style="text-align:center;">Monday’s Opening Price</td><td style="text-align:center;">The highest price at which the stock traded during the entire week</td><td style="text-align:center;">The lowest price at which the stock traded during the entire week</td><td style="text-align:center;">The closing price on Friday</td><td style="text-align:center;">52 candles for the entire year</td></tr><tr><td style="text-align:center;">Daily or EOD</td><td style="text-align:center;">The opening price of the day</td><td style="text-align:center;">The highest price at which the stock traded during the day</td><td style="text-align:center;">The lowest price at which the stock traded during the entire day</td><td style="text-align:center;">The closing price of the day</td><td style="text-align:center;">One candle per day, 252 candles for the entire year</td></tr><tr><td style="text-align:center;">Intraday 30 minutes</td><td style="text-align:center;">The opening price at the beginning of the 1st minute</td><td style="text-align:center;">The highest price at which the stock traded during the 30-minute duration</td><td style="text-align:center;">The lowest price at which the stock traded during the 30-minute duration</td><td style="text-align:center;">The closing price as on the 30th minute</td><td style="text-align:center;">Approximately 12 candles per day</td></tr><tr><td style="text-align:center;">Intraday 15 minutes</td><td style="text-align:center;">The opening price at the beginning of the 1st minute</td><td style="text-align:center;">The highest price at which the stock traded during the 15-minute duration</td><td style="text-align:center;">The lowest price at which the stock traded during the 15-minute duration</td><td style="text-align:center;">The closing price as on the 15th minute</td><td style="text-align:center;">25 candles per day</td></tr><tr><td style="text-align:center;">Intraday 5 minutes</td><td style="text-align:center;">The opening price at the beginning of the 1st minute</td><td style="text-align:center;">The highest price at which the stock traded during the 5-minute duration</td><td style="text-align:center;">The lowest price at which the stock traded during the 5-minute duration</td><td style="text-align:center;">The closing price as on the 5th minute</td><td style="text-align:center;">75 candles per day</td></tr></tbody></table><p>As you can see from the table above, the number of candles (data points) increases when the time frame reduces. Based on the type of trader you are, you need to take a stand on the time frame you need.</p><p>The data can either be information or noise. As a trader, you need to filter information from noise. For instance, a long term investor is better off looking at weekly or monthly charts as this would provide information. While on the other hand an intraday trader executing 1 or 2 trades per day is better off looking at the end of the day (EOD) or at best 15 mins charts. Likewise, for a high-frequency trader, 1-minute charts can convey a lot of information.</p><p>So based on your stance as a trader, you need to choose a time frame. This is extremely crucial for your trading success because a successful trader looks for information and discards the noise.</p><div class="tip custom-block"><p class="custom-block-title">Key takeaways from this chapter</p><ol><li>Time frames play a very crucial role in defining trading success. One has to choose this carefully.</li><li>The number of candle increases as and when the frequency increases.</li><li>Traders should be in a position to discard noise from relevant information</li></ol></div><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',13)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/bstdxjSNrYo",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[h("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),n(r,null,{default:c(()=>[n(i)]),_:1})])}const b=o(m,[["render",y]]);export{T as __pageData,b as default};
